from _lib import *
lesson("inversion-negative-adverbials", "Inwersja", "Inwersja po wyrażeniach przeczących i ograniczających", 1,
 "Inwersja to zamiana miejscami podmiotu i operatora (do/does/did, have, be, can itd.) – tak jak w pytaniu – ale w zdaniu twierdzącym. Robimy ją, gdy zdanie zaczyna się od wyrażenia przeczącego lub ograniczającego: Never, Rarely, Seldom, Hardly … when, No sooner … than, Not only … but also, Not until, Only then, Under no circumstances, At no time, Little. Efekt: zdanie brzmi bardziej formalnie i emfatycznie.",
 "Używamy jej głównie w piśmie formalnym (eseje, raporty, przemówienia) i w wypowiedziach, które mają podkreślić zaskoczenie lub wagę informacji. W Part 4 (key word transformations) to jedna z najczęściej testowanych struktur. W rozmowie potocznej brzmi teatralnie – lepiej z niej rezygnować.",
 dict(scheme="Wyrażenie przeczące + operator + podmiot + czasownik główny", word_order="Never have I seen… / Not only did she win… / Only after the meeting did we realise…",
      affirmative=["Never have I seen such chaos.", "Rarely does he arrive on time.", "No sooner had we left than it started to rain."],
      negative=["Inwersja sama w sobie wyraża przeczenie – nie dodajemy not: Never have I… (nie: Never haven't I…)."],
      questions=["Struktura nie tworzy pytań; to szyk pytający w zdaniu oznajmującym."]),
 [X("Never have I been so embarrassed.", "Nigdy nie byłem tak zawstydzony.", "Never + present perfect → operator have przed podmiotem."),
  X("Rarely do we see such dedication.", "Rzadko widuje się takie zaangażowanie.", "Present simple → dodajemy do."),
  X("Seldom did she complain about her job.", "Rzadko narzekała na swoją pracę.", "Past simple → did + forma podstawowa (complain)."),
  X("Hardly had I sat down when the phone rang.", "Ledwie usiadłem, zadzwonił telefon.", "Hardly … when + past perfect w pierwszej części."),
  X("No sooner had the film started than the power went off.", "Ledwie zaczął się film, wysiadł prąd.", "No sooner łączy się z than, nie z when."),
  X("Not only did he lie, but he also blamed others.", "Nie tylko kłamał, ale też obwiniał innych.", "Inwersja tylko w części z not only."),
  X("Not until I read the report did I understand the problem.", "Dopiero gdy przeczytałem raport, zrozumiałem problem.", "Not until + zdanie → inwersja w zdaniu głównym."),
  X("Only then did they realise their mistake.", "Dopiero wtedy zdali sobie sprawę z błędu.", "Only then / Only later / Only after + inwersja."),
  X("Under no circumstances should you open this door.", "W żadnym wypadku nie otwieraj tych drzwi.", "Zakaz w stylu formalnym; operator should."),
  X("Little did she know that she was being watched.", "Nie miała pojęcia, że jest obserwowana.", "Little = wcale nie; typowe w narracji."),
  X("At no time was the public informed of the risk.", "Ani razu nie poinformowano opinii publicznej o ryzyku.", "Strona bierna: operator was przed podmiotem."),
  X("Only by working together can we solve this.", "Tylko współpracując, możemy to rozwiązać.", "Only by + -ing + inwersja z modalnym can.")],
 [C("Never have I seen… vs I have never seen…", "Treść ta sama; wersja z inwersją jest formalna i mocniej akcentuje 'never'.", "Inwersja: esej, przemówienie, Part 4. Zwykły szyk: rozmowa, e-mail nieformalny."),
  C("Hardly … when vs No sooner … than", "Znaczą to samo (ledwie… gdy). Różnią się drugim słowem: when/before po hardly, than po no sooner.", "Wybierz parę zgodnie z pierwszym słowem – mieszanie (no sooner … when) to błąd."),
  C("Only after X did… vs Only X did…", "Inwersja następuje w zdaniu głównym, nie w części z only after.", "Only after he left did I notice (nie: Only after did he leave…).")],
 [W("Never I have seen such a mess.", "Never have I seen such a mess.", "Po never na początku operator musi stać przed podmiotem."),
  W("Rarely he goes out.", "Rarely does he go out.", "W present simple trzeba dodać does, a czasownik wraca do formy podstawowej."),
  W("No sooner had we arrived when it rained.", "No sooner had we arrived than it rained.", "No sooner zawsze z than."),
  W("Not only she sings, but she also dances.", "Not only does she sing, but she also dances.", "Polski szyk nie ma inwersji – w angielskim po not only jest wymagana."),
  W("Not until I saw her I recognised her.", "Not until I saw her did I recognise her.", "Inwersja dotyczy drugiej części (zdania głównego).")],
 ["Gdy never/rarely/only nie stoją na początku zdania, inwersji nie ma: I have never seen it.",
  "Not only może łączyć wyrazy, a nie zdania – wtedy bez inwersji: Not only Tom but also Ann came.",
  "Only + podmiot (Only Tom knew) nie wywołuje inwersji, bo only odnosi się do podmiotu.",
  "Little w znaczeniu 'mało' (Little is known) nie wymaga inwersji – to podmiot."],
 [dict(en="Seldom, if ever, has a government faced such opposition.", pl="Rzadko kiedy, jeśli w ogóle, rząd mierzył się z takim sprzeciwem.", note="'if ever' wzmacnia seldom/rarely – brzmi bardzo C1."),
  dict(en="Nowhere is this more evident than in our schools.", pl="Nigdzie nie widać tego wyraźniej niż w naszych szkołach.", note="Nowhere + inwersja – świetne zdanie do eseju."),
  dict(en="So severe was the damage that the bridge had to be closed.", pl="Szkody były tak poważne, że most trzeba było zamknąć.", note="So + przymiotnik + inwersja + that.")],
 [G("Never ___ (I / see) such a beautiful sunset.", ["have I seen"], "Never + present perfect: operator have przed podmiotem."),
  G("Rarely ___ (she / ask) for help.", ["does she ask"], "Present simple wymaga does; ask w formie podstawowej."),
  G("No sooner ___ (we / sit) down than the alarm went off.", ["had we sat"], "No sooner + past perfect z inwersją."),
  M("Hardly had he finished speaking ___ the audience began to applaud.", ["when", "than", "that", "then"], "when", "Hardly … when (lub before).", {"than": "Than łączy się z no sooner, nie z hardly.", "that": "That nie wprowadza tu zdania czasowego.", "then": "Then to przysłówek, nie spójnik."}),
  G("Not only ___ (he / forget) my birthday, but he also lost the present.", ["did he forget"], "Past simple → did + forget."),
  G("Under no circumstances ___ (passengers / leave) their luggage unattended.", ["should passengers leave", "must passengers leave"], "Formalny zakaz: should/must + podmiot + forma podstawowa."),
  M("Only after the results were published ___ the mistake.", ["did they notice", "they noticed", "they did notice", "noticed they"], "did they notice", "Inwersja w zdaniu głównym po only after.", {"they noticed": "Brak inwersji po only after.", "they did notice": "Do pomocnicze musi stać przed podmiotem.", "noticed they": "Inwersję robimy z operatorem, nie z czasownikiem głównym."}),
  K("I didn't realise the danger until later.", "ONLY", "___ the danger.", ["Only later did I realise"], "Only later + inwersja: did I realise."),
  E("Little she knew what was about to happen.", ["Little did she know what was about to happen.", "little did she know"], "Little na początku → did + podmiot + know.")],
 [G("Seldom ___ (we / have) such an opportunity.", ["do we have"], "Present simple: do we have."),
  G("At no time ___ (the staff / inform) about the changes.", ["were the staff informed", "was the staff informed"], "Strona bierna w past: were/was + podmiot + informed."),
  K("As soon as she arrived, the meeting began.", "SOONER", "No ___ the meeting began.", ["sooner had she arrived than"], "No sooner + had + podmiot + past participle + than."),
  K("He not only plays the violin but also composes.", "DOES", "Not only ___ the violin, but he also composes.", ["does he play"], "Present simple: does he play."),
  K("You must not tell anyone about this.", "CIRCUMSTANCES", "Under ___ anyone about this.", ["no circumstances must you tell", "no circumstances should you tell"], "Under no circumstances + must/should + you."),
  T("Nigdy wcześniej nie widziałem tak długiej kolejki.", ["Never before have I seen such a long queue.", "Never have I seen such a long queue before.", "Never before had I seen such a long queue."], "Never (before) + have I seen.")])
